effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    vec3 x;
    x.r = smoothstep(0.05, 0.95, c.r);
    x.g = pow(c.g, 1.25);
    x.b = mix(c.b, 0.45, 0.25);
    x = (x-0.5)*1.15 + 0.5;
    gl_FragColor = vec4(clamp(mix(c,x,amount),0.0,1.0),1.0)*src.a;
}
